/** True when the catalog tool has a live execute handler (vs catalog-only). */
export function isMcpToolExecutable(toolId: string): boolean {
  return EXECUTABLE_MCP_TOOL_IDS.has(toolId);
}

/**
 * OAuth / third-party connector stubs — executable paths exist but return
 * oauth_required until partner credentials are configured. Excluded from
 * partner curated claims (honesty-first). aws_s3_* stays in partner curated.
 */
export const OAUTH_STUB_MCP_TOOL_IDS: ReadonlySet<string> = new Set<string>([
  'google_drive_list', 'google_drive_download', 'microsoft_onedrive_list', 'microsoft_onedrive_download',
  'sharepoint_list', 'sharepoint_download', 'box_storage_list', 'dropbox_list_files',
  'slack_post_message', 'microsoft_teams_post_message', 'notion_fetch_page',
  'gmail_create_draft', 'outlook_create_draft', 'google_calendar_create_event', 'outlook_calendar_create_event',
  'docusign_envelope_status', 'adobe_sign_status', 'salesforce_matter_sync', 'hubspot_contact_lookup',
  'razorpay_payment_status', 'stripe_invoice_fetch', 'zoom_meeting_create',
  'asana_task_create', 'jira_issue_create', 'trello_card_create',
]);

/**
 * Partner-facing curated gateway MCP tools (Wave A honesty): live handlers only;
 * no DocuSign/iManage/Drive claims. Target band with MCP-server API tools: 120–140.
 */
export const PARTNER_CURATED_MCP_TOOL_IDS: ReadonlySet<string> = new Set(
  [...EXECUTABLE_MCP_TOOL_IDS].filter((id) => !OAUTH_STUB_MCP_TOOL_IDS.has(id)),
);

export function isPartnerCuratedMcpTool(toolId: string): boolean {
  return PARTNER_CURATED_MCP_TOOL_IDS.has(toolId);
}

export function isMcpToolCatalogArchived(tool: McpTool): boolean {
  if (tool.catalogArchived === true) return true;
  // Partner default list = curated live set; rest of catalog is archived from claims.
  return !PARTNER_CURATED_MCP_TOOL_IDS.has(tool.id);
}

