// ── Category lookup index ───────────────────────────────────────────────────
export const TOOLS_BY_CATEGORY = NV_MCP_TOOLS_REGISTRY.reduce<Record<string, McpTool[]>>(
  (acc, tool) => {
    if (!acc[tool.category]) acc[tool.category] = [];
    acc[tool.category].push(tool);
    return acc;
  },
  {}
);

// ── Tool ID lookup index ────────────────────────────────────────────────────
export const TOOL_BY_ID = NV_MCP_TOOLS_REGISTRY.reduce<Record<string, McpTool>>(
  (acc, tool) => {
    acc[tool.id] = tool;
    return acc;
  },
  {}
);
